(()=>{
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
 const nav=document.querySelector('#categories');const indicator=document.createElement('span');indicator.className='category-indicator';indicator.setAttribute('aria-hidden','true');nav.append(indicator);
 function positionIndicator(){const active=nav.querySelector('[aria-pressed="true"]');if(active){indicator.style.setProperty('--indicator-left',active.offsetLeft+'px');indicator.style.setProperty('--indicator-width',active.offsetWidth+'px')}}
 const observer='IntersectionObserver' in window?new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('reveal-visible');observer.unobserve(entry.target)}})},{threshold:.06,rootMargin:'30px 0px'}):null;
 function refresh(){positionIndicator();if(!observer||reduced.matches)return;observer.disconnect();document.querySelectorAll('.photo-card,.section-title,.section-description').forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--reveal-delay',el.classList.contains('photo-card')?`${(i%3)*65}ms`:'0ms');observer.observe(el)});onScroll()}
 let pending=false;function onScroll(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;const max=document.documentElement.scrollHeight-window.innerHeight;document.documentElement.style.setProperty('--page-progress',max>0?Math.min(1,window.scrollY/max):0);if(!reduced.matches)document.documentElement.style.setProperty('--stamp-turn',`${window.scrollY*.025}deg`);document.querySelector('.filterbar').classList.toggle('is-stuck',document.querySelector('.filterbar').getBoundingClientRect().top<=0)})}
 document.addEventListener('pointermove',e=>{if(reduced.matches||!matchMedia('(hover:hover)').matches)return;const card=e.target.closest('.photo-card');if(!card)return;const rect=card.getBoundingClientRect();card.style.setProperty('--tilt-x',`${((e.clientX-rect.left)/rect.width-.5)*4}deg`);card.style.setProperty('--tilt-y',`${-((e.clientY-rect.top)/rect.height-.5)*4}deg`)});
 document.addEventListener('pointerout',e=>{const card=e.target.closest('.photo-card');if(card&&!card.contains(e.relatedTarget)){card.style.removeProperty('--tilt-x');card.style.removeProperty('--tilt-y')}});
 const dialog=document.querySelector('dialog');let closeTimer;
 function closeDialog(){if(!dialog.open)return true;if(reduced.matches){dialog.close();return true}if(closeTimer)return true;dialog.classList.remove('is-opening');dialog.classList.add('is-closing');closeTimer=setTimeout(()=>{dialog.close();dialog.classList.remove('is-closing');closeTimer=null},200);return true}
 dialog.addEventListener('cancel',event=>{event.preventDefault();closeDialog()});
 window.sahraMotion={refresh,closeDialog,openDialog(){clearTimeout(closeTimer);closeTimer=null;dialog.classList.remove('is-closing');dialog.classList.remove('is-opening');void dialog.offsetWidth;dialog.classList.add('is-opening')},heart(id){if(reduced.matches)return;document.querySelectorAll(`[data-save="${id}"]`).forEach(el=>el.animate([{transform:'scale(1)'},{transform:'scale(1.35) rotate(-12deg)',offset:.4},{transform:'scale(1)'}],{duration:450,easing:'cubic-bezier(.2,.8,.2,1)'}));document.querySelector('#saved-count').animate([{transform:'translateY(0)'},{transform:'translateY(-4px)'},{transform:'translateY(0)'}],{duration:350})}};
 if(observer&&!reduced.matches)document.body.classList.add('motion-ready');refresh();window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',()=>{positionIndicator();onScroll()});document.fonts.ready.then(positionIndicator);reduced.addEventListener('change',()=>{document.body.classList.toggle('motion-ready',!reduced.matches&&!!observer);refresh()});onScroll();
})();
